import random
import time
import itertools

def construct():
    points = list(range(16))
    all_triples = list(itertools.combinations(points, 3))
    num_triples = len(all_triples)
    
    # Map triple to index
    triple_to_idx = {t: i for i, t in enumerate(all_triples)}
    
    # Precompute hyperedges (K(2,2,2) configurations)
    # A hyperedge is a set of 8 triples.
    # Generated by choosing 6 distinct points and partitioning into 3 pairs.
    hyperedges = []
    triple_to_hyperedges = [[] for _ in range(num_triples)]
    
    # Iterate over all combinations of 6 points
    for p6 in itertools.combinations(points, 6):
        # p6 is (p0, p1, p2, p3, p4, p5)
        # We need to partition into 3 pairs.
        # There are 15 such partitions.
        # We can generate them by fixing p0's partner.
        # Partners for p0 can be p1, p2, p3, p4, p5.
        # If p0 paired with p1, remaining are p2,p3,p4,p5.
        # Partitions of 4 items into 2 pairs: 3 ways.
        # Total 5 * 3 = 15.
        
        # To avoid duplicates, we can just iterate through all 15 permutations of pairs
        # or use a standard combinatorial generation.
        
        # Let's just generate all 15 partitions explicitly for clarity and correctness.
        # A partition is a list of 3 pairs.
        # We can represent it as ( (a,a'), (b,b'), (c,c') )
        # The 8 triples are all combinations of picking one from each pair.
        
        # Generate all 15 partitions of 6 items into 3 pairs
        # This is a known combinatorial object.
        # We can hardcode the logic or use a small helper.
        
        # Helper to generate partitions of [0,1,2,3,4,5] into 3 pairs
        # We'll use the fact that the number of perfect matchings in K6 is 15.
        
        # For each of the 15 matchings:
        # 1. Identify the 3 pairs.
        # 2. Generate the 8 triples.
        # 3. Check if all 8 triples are in triple_to_idx (they are, since all triples are valid).
        # 4. Add the set of 8 triple indices to hyperedges.
        
        # Efficient way to get the 15 matchings:
        # Fix pair (0,1). Remaining 2,3,4,5.
        #   Pair (2,3), remaining 4,5 -> (4,5). Matching: [(0,1),(2,3),(4,5)]
        #   Pair (2,4), remaining 3,5 -> (3,5). Matching: [(0,1),(2,4),(3,5)]
        #   Pair (2,5), remaining 3,4 -> (3,4). Matching: [(0,1),(2,5),(3,4)]
        # Fix pair (0,2). Remaining 1,3,4,5.
        #   Pair (1,3), remaining 4,5 -> (4,5). Matching: [(0,2),(1,3),(4,5)]
        #   ... and so on.
        
        # Let's just iterate through all permutations of the 6 points and group?
        # No, that's 720.
        
        # Let's use a recursive generator or just list them.
        # Since 15 is small, we can hardcode the relative indices.
        
        # Relative indices for 6 items: 0,1,2,3,4,5
        # The 15 partitions are:
        partitions = [
            [(0,1),(2,3),(4,5)],
            [(0,1),(2,4),(3,5)],
            [(0,1),(2,5),(3,4)],
            [(0,2),(1,3),(4,5)],
            [(0,2),(1,4),(3,5)],
            [(0,2),(1,5),(3,4)],
            [(0,3),(1,2),(4,5)],
            [(0,3),(1,4),(2,5)],
            [(0,3),(1,5),(2,4)],
            [(0,4),(1,2),(3,5)],
            [(0,4),(1,3),(2,5)],
            [(0,4),(1,5),(2,3)],
            [(0,5),(1,2),(3,4)],
            [(0,5),(1,3),(2,4)],
            [(0,5),(1,4),(2,3)]
        ]
        
        for part in partitions:
            # part is list of 3 pairs of relative indices
            # Map relative indices to actual points in p6
            pairs = []
            for r1, r2 in part:
                pairs.append((p6[r1], p6[r2]))
            
            # Generate 8 triples
            h_triples = []
            for i in range(2):
                for j in range(2):
                    for k in range(2):
                        a = pairs[0][0] if i == 0 else pairs[0][1]
                        b = pairs[1][0] if j == 0 else pairs[1][1]
                        c = pairs[2][0] if k == 0 else pairs[2][1]
                        t = tuple(sorted((a, b, c)))
                        h_triples.append(t)
            
            # Convert to indices
            h_indices = [triple_to_idx[t] for t in h_triples]
            hyperedges.append(h_indices)
            
            # Update triple_to_hyperedges
            h_idx = len(hyperedges) - 1
            for t_idx in h_indices:
                triple_to_hyperedges[t_idx].append(h_idx)
                
    num_hyperedges = len(hyperedges)
    
    best_set = set()
    best_size = 0
    start_time = time.time()
    time_limit = 115
    
    random.seed(42)
    
    def is_valid_add(t_idx, counts, current_set):
        # Check if adding t_idx violates any hyperedge
        # current_set contains t_idx? No, we assume it doesn't.
        for h_idx in triple_to_hyperedges[t_idx]:
            if counts[h_idx] == 7:
                # Adding this would make it 8
                return False
        return True

    def try_greedy():
        current_set = set()
        counts = [0] * num_hyperedges
        
        # Shuffle triples
        indices = list(range(num_triples))
        random.shuffle(indices)
        
        for t_idx in indices:
            if time.time() - start_time > time_limit:
                break
            if is_valid_add(t_idx, counts, current_set):
                current_set.add(t_idx)
                for h_idx in triple_to_hyperedges[t_idx]:
                    counts[h_idx] += 1
                    
        # Local improvement: Try to add more
        # Iterate through all triples not in set, try to add
        # This is O(N * 1716) which is fine
        for t_idx in range(num_triples):
            if time.time() - start_time > time_limit:
                break
            if t_idx not in current_set:
                if is_valid_add(t_idx, counts, current_set):
                    current_set.add(t_idx)
                    for h_idx in triple_to_hyperedges[t_idx]:
                        counts[h_idx] += 1
                        
        # Swap phase: Try to swap to unlock more
        # We'll do a few rounds of random swaps
        for _ in range(50):
            if time.time() - start_time > time_limit:
                break
            if not current_set:
                break
            # Pick random out
            t_out = random.choice(list(current_set))
            # Temporarily remove
            current_set.discard(t_out)
            for h_idx in triple_to_hyperedges[t_out]:
                counts[h_idx] -= 1
            
            # Try to add any valid in
            added = False
            for t_in in range(num_triples):
                if t_in == t_out:
                    continue
                if t_in not in current_set:
                    if is_valid_add(t_in, counts, current_set):
                        current_set.add(t_in)
                        for h_idx in triple_to_hyperedges[t_in]:
                            counts[h_idx] += 1
                        added = True
                        break # Only add one per swap step for simplicity? 
                        # Or try to add multiple?
                        
            if not added:
                # Revert
                current_set.add(t_out)
                for h_idx in triple_to_hyperedges[t_out]:
                    counts[h_idx] += 1
            else:
                # After swap, try to add more
                for t_add in range(num_triples):
                    if time.time() - start_time > time_limit:
                        break
                    if t_add not in current_set:
                        if is_valid_add(t_add, counts, current_set):
                            current_set.add(t_add)
                            for h_idx in triple_to_hyperedges[t_add]:
                                counts[h_idx] += 1
                            
        return current_set, counts

    attempts = 0
    while time.time() - start_time < time_limit and attempts < 200:
        attempts += 1
        current_set, counts = try_greedy()
        
        if len(current_set) > best_size:
            best_size = len(current_set)
            best_set = set(current_set)
            
        # If we found a large set, do more local search on it?
        # The try_greedy already does local search.
        
    # Convert best_set indices back to triples
    return [list(all_triples[i]) for i in best_set]
